use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn to_lower(s: &[u8]) -> Vec<u8> {
    s.iter()
        .map(|&b| if b >= b'A' && b <= b'Z' { b + 32 } else { b })
        .collect()
}

fn strip_prefix(s: &[u8]) -> Vec<u8> {
    if s.len() >= 4 && &s[0..4] == b"xn--" {
        s[4..].to_vec()
    } else {
        s.to_vec()
    }
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let default = b"multi.level.domain.name.test".to_vec();
    let domain: Vec<u8> = if args.len() > 1 {
        args[1].as_bytes().to_vec()
    } else {
        default
    };

    // 1 to_ascii
    let mut r1 = b"xn--".to_vec();
    r1.extend_from_slice(&to_lower(&domain));
    // 2 to_unicode(r1)
    let r2 = strip_prefix(&r1);
    // 3 punycode_encode
    let mut r3 = b"xn--".to_vec();
    r3.extend_from_slice(&domain);
    // 4 punycode_decode(r3)
    let r4 = strip_prefix(&r3);
    // 5 is_valid_domain
    let r5 = !domain.is_empty() && domain.len() <= 255;
    // 6
    let r6 = true;
    // 7 is_ascii_domain
    let r7 = domain.iter().all(|&b| b < 0x80);
    // 8 is_idn_domain
    let r8 = domain.iter().any(|&b| b >= 0x80);
    // 9
    let r9 = b"mixedcase".to_vec();
    // 10 normalize
    let r10 = to_lower(&domain);
    // 11 extract_tld
    let r11: Vec<u8> = match domain.iter().rposition(|&b| b == b'.') {
        Some(i) => domain[i + 1..].to_vec(),
        None => domain.clone(),
    };
    // 12 count_labels
    let r12 = domain.iter().filter(|&&b| b == b'.').count() + 1;

    let stdout = std::io::stdout();
    let mut o = stdout.lock();
    o.write_all(&r1).unwrap();
    o.write_all(b"\n").unwrap();
    o.write_all(&r2).unwrap();
    o.write_all(b"\n").unwrap();
    o.write_all(&r3).unwrap();
    o.write_all(b"\n").unwrap();
    o.write_all(&r4).unwrap();
    o.write_all(b"\n").unwrap();
    o.write_all(if r5 { b"1\n" } else { b"0\n" }).unwrap();
    o.write_all(if r6 { b"1\n" } else { b"0\n" }).unwrap();
    o.write_all(if r7 { b"1\n" } else { b"0\n" }).unwrap();
    o.write_all(if r8 { b"1\n" } else { b"0\n" }).unwrap();
    o.write_all(&r9).unwrap();
    o.write_all(b"\n").unwrap();
    o.write_all(&r10).unwrap();
    o.write_all(b"\n").unwrap();
    o.write_all(&r11).unwrap();
    o.write_all(b"\n").unwrap();
    o.write_all(format!("{}\n", r12).as_bytes()).unwrap();
    o.flush().unwrap();
}

use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::process::Command;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % (n as u64)) as usize
    }
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02x}", x)).collect()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let iters: usize = args.get(1).map(|s| s.parse().unwrap()).unwrap_or(1000);
    let seed: u64 = args.get(2).map(|s| s.parse().unwrap()).unwrap_or(0x12345678);
    let mode: usize = args.get(3).map(|s| s.parse().unwrap()).unwrap_or(0);
    let mut rng = Rng(seed);

    // alphabet heavily biased toward the interesting bytes for this lens
    let alpha: Vec<u8> = match mode {
        // mode 0: xn--/dot heavy ascii
        0 => b"xnXN-.aAzZ019_ ".to_vec(),
        // mode 1: full byte range 1..=255
        1 => (1u8..=255).collect(),
        // mode 2: dots + case + high bytes
        2 => {
            let mut v: Vec<u8> = b"xnXN-......aA".to_vec();
            v.extend(0x80u8..=0xffu8);
            v
        }
        // mode 3: printable ascii
        _ => (0x20u8..=0x7eu8).collect(),
    };

    let mut fails = 0usize;
    for i in 0..iters {
        let len = match rng.below(10) {
            0 => rng.below(5),
            1..=6 => rng.below(20),
            7 | 8 => rng.below(80),
            _ => rng.below(300),
        };
        let mut buf: Vec<u8> = Vec::with_capacity(len);
        // sometimes force an xn-- style prefix
        match rng.below(6) {
            0 => buf.extend_from_slice(b"xn--"),
            1 => buf.extend_from_slice(b"XN--"),
            2 => buf.extend_from_slice(b"xn-"),
            3 => buf.extend_from_slice(b"xn---"),
            _ => {}
        }
        for _ in 0..len {
            let c = alpha[rng.below(alpha.len())];
            buf.push(c);
        }

        let a = OsString::from_vec(buf.clone());
        let o1 = Command::new("/workspace/dataset/test12_executable")
            .arg(&a)
            .output()
            .expect("spawn bin");
        let o2 = Command::new("/tmp/model").arg(&a).output().expect("spawn model");
        if o1.stdout != o2.stdout || o1.status.code() != o2.status.code() || !o1.stderr.is_empty() {
            fails += 1;
            println!("MISMATCH iter={} seed={} mode={}", i, seed, mode);
            println!("  input_hex = {}", hex(&buf));
            println!("  input_len = {}", buf.len());
            println!("  bin_out   = {}", hex(&o1.stdout));
            println!("  mod_out   = {}", hex(&o2.stdout));
            println!("  bin_err   = {}", hex(&o1.stderr));
            println!("  status    = {:?} / {:?}", o1.status.code(), o2.status.code());
            if fails > 8 {
                println!("too many mismatches, stopping");
                break;
            }
        }
    }
    println!("fuzz done: iters={} seed={} mode={} mismatches={}", iters, seed, mode, fails);
}

use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::process::Command;

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02x}", x)).collect()
}

fn run(buf: &[u8]) -> (Vec<u8>, Vec<u8>, Vec<u8>, Option<i32>, Option<i32>) {
    let a = OsString::from_vec(buf.to_vec());
    let o1 = Command::new("/workspace/dataset/test12_executable")
        .arg(&a)
        .output()
        .expect("bin");
    let o2 = Command::new("/tmp/model").arg(&a).output().expect("mod");
    (
        o1.stdout,
        o2.stdout,
        o1.stderr,
        o1.status.code(),
        o2.status.code(),
    )
}

fn main() {
    let mut n = 0usize;
    let mut bad = 0usize;
    // every byte value 0x01..=0xff in 6 structural positions relevant to the lens
    for b in 1u8..=255 {
        let cases: Vec<Vec<u8>> = vec![
            vec![b],                                       // bare
            [b"xn--".as_ref(), &[b]].concat(),              // after xn-- prefix
            [&[b], b"xn--".as_ref()].concat(),              // before xn--
            [b"a.".as_ref(), &[b]].concat(),                // as TLD
            [&[b], b".".as_ref()].concat(),                 // label then empty tld
            [b"A.".as_ref(), &[b], b".Z".as_ref()].concat(), // middle label
            [b"xn".as_ref(), &[b], b"--q".as_ref()].concat(),// inside prefix region
            [b"x".as_ref(), &[b], b"--q".as_ref()].concat(), // inside prefix region 2
        ];
        for c in cases {
            n += 1;
            let (o1, o2, e1, s1, s2) = run(&c);
            if o1 != o2 || s1 != s2 || !e1.is_empty() {
                bad += 1;
                println!("MISMATCH input_hex={}", hex(&c));
                println!("  bin={}", hex(&o1));
                println!("  mod={}", hex(&o2));
                println!("  err={} status={:?}/{:?}", hex(&e1), s1, s2);
                if bad > 10 {
                    println!("stopping");
                    return;
                }
            }
        }
    }
    println!("byte sweep done: probes={} mismatches={}", n, bad);
}
